    79→/// A table view wrapper that displays the timeline of a room.
    80→struct TimelineViewRepresentable: UIViewControllerRepresentable {
    81→    @EnvironmentObject private var viewModelContext: TimelineViewModel.Context
    82→
    83→    func makeUIViewController(context: Context) -> TimelineTableViewController {
    84→        TimelineTableViewController(coordinator: context.coordinator,
    85→                                    isScrolledToBottom: $viewModelContext.isScrolledToBottom,
    86→                                    scrollToBottomPublisher: viewModelContext.viewState.timelineState.scrollToBottomPublisher)
    87→    }
    88→    
    89→    func updateUIViewController(_ uiViewController: TimelineTableViewController, context: Context) {
    90→        context.coordinator.update(tableViewController: uiViewController)
    91→    }
    92→    
    93→    func makeCoordinator() -> Coordinator {
    94→        Coordinator(viewModelContext: viewModelContext)
    95→    }
    96→    
    97→    // MARK: - Coordinator
    98→    
    99→    @MainActor
   100→    class Coordinator {
   101→        let context: TimelineViewModel.Context
   102→        
   103→        init(viewModelContext: TimelineViewModel.Context) {
   104→            context = viewModelContext
   105→        }
   106→        
   107→        /// Updates the specified table view's properties from the current view state.
   108→        func update(tableViewController: TimelineTableViewController) {
   109→            if tableViewController.isSwitchingTimelines != context.viewState.timelineState.isSwitchingTimelines {
   110→                // Must come before timelineItemsDictionary in order to disable animations.
   111→                tableViewController.isSwitchingTimelines = context.viewState.timelineState.isSwitchingTimelines
   112→            }
   113→            if tableViewController.timelineItemsDictionary != context.viewState.timelineState.itemsDictionary {
   114→                tableViewController.timelineItemsDictionary = context.viewState.timelineState.itemsDictionary
   115→            }
   116→            if tableViewController.paginationState != context.viewState.timelineState.paginationState {
   117→                tableViewController.paginationState = context.viewState.timelineState.paginationState
   118→            }
   119→            if tableViewController.isLive != context.viewState.timelineState.isLive {
   120→                tableViewController.isLive = context.viewState.timelineState.isLive
   121→            }
   122→            if tableViewController.focussedEvent != context.viewState.timelineState.focussedEvent {
   123→                tableViewController.focussedEvent = context.viewState.timelineState.focussedEvent
   124→            }
   125→            if tableViewController.hideTimelineMedia != context.viewState.hideTimelineMedia {
   126→                tableViewController.hideTimelineMedia = context.viewState.hideTimelineMedia
   127→            }
   128→            
   129→            if tableViewController.typingMembers.members != context.viewState.typingMembers {
   130→                tableViewController.setTypingMembers(context.viewState.typingMembers)
   131→            }
   132→        }
   133→        
   134→        func send(viewAction: TimelineViewAction) {
   135→            context.send(viewAction: viewAction)
   136→        }
   137→    }
   138→}
