    13→struct RoomScreen: View {
    14→    @ObservedObject private var context: RoomScreenViewModelType.Context
    15→    @ObservedObject private var timelineContext: TimelineViewModelType.Context
    16→    let composerToolbar: ComposerToolbar
    17→    @Environment(\.accessibilityVoiceOverEnabled) private var isVoiceOverEnabled
    18→
    19→    init(context: RoomScreenViewModelType.Context,
    20→         timelineContext: TimelineViewModelType.Context,
    21→         composerToolbar: ComposerToolbar) {
    22→        self.context = context
    23→        self.timelineContext = timelineContext
    24→        self.composerToolbar = composerToolbar
    25→    }
    26→
    27→    var body: some View {
    28→        TimelineView(timelineContext: timelineContext)
    29→            .overlay(alignment: .bottomTrailing) {
    30→                TimelineScrollToBottomButton(isVisible: isAtBottomAndLive) {
    31→                    timelineContext.send(viewAction: .scrollToBottom)
    32→                }
    33→                .accessibilityIdentifier(A11yIdentifiers.roomScreen.scrollToBottom)
    34→            }
    35→            .background(Color.compound.bgCanvasDefault.ignoresSafeArea())
    36→            .topBanner(pinnedItemsBanner, isVisible: context.viewState.shouldShowPinnedEventsBanner && !isVoiceOverEnabled)
    37→            // This can overlay on top of the pinnedItemsBanner
    38→            .topBanner(knockRequestsBanner, isVisible: context.viewState.shouldSeeKnockRequests)
    39→            .safeAreaInset(edge: .top) {
    40→                // When VoiceOver is enabled, the table view isn't reversed and the scroll gestures
    41→                // don't trigger meaning the banner never hides itself and so the .overlay layout
    42→                // above permanently obscures the top of the timeline. So whenever VoiceOver is
    43→                // enabled we use a safe area inset to vertically stack it above the timeline.
    44→                if context.viewState.shouldShowPinnedEventsBanner, isVoiceOverEnabled {
    45→                    pinnedItemsBanner
    46→                }
    47→            }
    48→            .safeAreaInset(edge: .bottom, spacing: 0) {
    49→                VStack(spacing: 0) {
    50→                    RoomScreenFooterView(details: context.viewState.footerDetails,
    51→                                         mediaProvider: context.mediaProvider) { action in
    52→                        context.send(viewAction: .footerViewAction(action))
    53→                    }
    54→                    
    55→                    composer
    56→                        .padding(.top, 8)
    57→                        .background(Color.compound.bgCanvasDefault.ignoresSafeArea())
    58→                        .environmentObject(timelineContext)
    59→                        .environment(\.timelineContext, timelineContext)
    60→                        // Make sure the reply header honours the hideTimelineMedia setting too.
    61→                        .environment(\.shouldAutomaticallyLoadImages, !timelineContext.viewState.hideTimelineMedia)
    62→                }
    63→            }
    64→            .toolbarRole(RoomHeaderView.toolbarRole)
    65→            .navigationTitle(L10n.screenRoomTitle) // Hidden but used for back button text.
    66→            .navigationBarTitleDisplayMode(.inline)
    67→            .toolbar { toolbar }
    68→            .toolbarBackground(.visible, for: .navigationBar) // Fix the toolbar's background.
    69→            .overlay { loadingIndicator }
    70→            .alert(item: $context.alertInfo)
    71→            .timelineMediaPreview(viewModel: $context.mediaPreviewViewModel)
    72→            .track(screen: .Room)
    73→            .sentryTrace("\(Self.self)")
    74→    }
    75→    
    76→    private var pinnedItemsBanner: some View {
    77→        PinnedItemsBannerView(state: context.viewState.pinnedEventsBannerState,
    78→                              onMainButtonTap: { context.send(viewAction: .tappedPinnedEventsBanner) },
    79→                              onViewAllButtonTap: { context.send(viewAction: .viewAllPins) })
    80→    }
    81→    
    82→    private var knockRequestsBanner: some View {
    83→        KnockRequestsBannerView(requests: context.viewState.displayedKnockRequests,
    84→                                onDismiss: dismissKnockRequestsBanner,
    85→                                onAccept: context.viewState.canAcceptKnocks ? acceptKnockRequest : nil,
    86→                                onViewAll: onViewAllKnockRequests,
    87→                                mediaProvider: context.mediaProvider)
    88→            .padding(.top, 16)
    89→    }
    90→    
    91→    private func dismissKnockRequestsBanner() {
    92→        context.send(viewAction: .dismissKnockRequests)
    93→    }
    94→    
    95→    private func acceptKnockRequest(eventID: String) {
    96→        context.send(viewAction: .acceptKnock(eventID: eventID))
    97→    }
    98→    
    99→    private func onViewAllKnockRequests() {
   100→        context.send(viewAction: .viewKnockRequests)
   101→    }
   102→    
   103→    private var isAtBottomAndLive: Bool {
   104→        timelineContext.isScrolledToBottom && timelineContext.viewState.timelineState.isLive
   105→    }
   106→    
   107→    @ViewBuilder
   108→    private var composer: some View {
   109→        if context.viewState.hasSuccessor {
   110→            tombstonedDialogue
   111→        } else if context.viewState.canSendMessage, !ProcessInfo.isRunningAccessibilityTests {
   112→            // We are not sure why but when wrapped in the room screen the composer toolbar breaks the accessibility tests
   113→            composerToolbar
   114→        } else {
   115→            ComposerDisabledView()
   116→        }
   117→    }
   118→    
   119→    private var tombstonedDialogue: some View {
   120→        VStack(spacing: 16) {
   121→            Text(L10n.screenRoomTimelineTombstonedRoomMessage)
   122→                .font(.compound.bodyMD)
   123→                .foregroundStyle(.compound.textPrimary)
   124→            
   125→            Button {
   126→                context.send(viewAction: .displaySuccessorRoom)
   127→            } label: {
   128→                Text(L10n.screenRoomTimelineTombstonedRoomAction)
   129→                    .frame(maxWidth: .infinity)
   130→            }
   131→            .buttonStyle(.compound(.primary, size: .medium))
   132→        }
   133→        .padding(.top, 16)
   134→        .padding(.horizontal, 16)
   135→        .padding(.bottom, 12)
   136→        .highlight(gradient: .compound.info,
   137→                   borderColor: .compound.borderInfoSubtle,
   138→                   backgroundColor: .compound.bgCanvasDefault)
   139→    }
   140→    
   141→    @ViewBuilder
   142→    private var loadingIndicator: some View {
   143→        if timelineContext.viewState.showLoading {
   144→            ProgressView()
   145→                .progressViewStyle(.circular)
   146→                .tint(.compound.textPrimary)
   147→                .padding(16)
   148→                .background(.ultraThickMaterial)
   149→                .cornerRadius(8)
   150→        }
   151→    }
   152→    
   153→    @ToolbarContentBuilder
   154→    private var toolbar: some ToolbarContent {
   155→        // .principal + .primaryAction works better than .navigation leading + trailing
   156→        // as the latter disables interaction in the action button for rooms with long names
   157→        ToolbarItem(placement: .principal) {
   158→            RoomHeaderView(roomName: context.viewState.roomTitle,
   159→                           roomAvatar: context.viewState.roomAvatar,
   160→                           dmRecipientVerificationState: context.viewState.dmRecipientVerificationState,
   161→                           roomHistorySharingState: context.viewState.roomHistorySharingState,
   162→                           mediaProvider: context.mediaProvider) {
   163→                context.send(viewAction: .displayRoomDetails)
   164→            }
   165→        }
   166→        
   167→        if !ProcessInfo.processInfo.isiOSAppOnMac {
   168→            ToolbarItem(placement: .primaryAction) {
   169→                if context.viewState.shouldShowCallButton {
   170→                    callButton
   171→                        .disabled(!context.viewState.canJoinCall)
   172→                }
   173→            }
   174→        }
   175→    }
   176→    
   177→    @ViewBuilder
   178→    private var callButton: some View {
   179→        if context.viewState.hasOngoingCall {
   180→            JoinCallButton {
   181→                context.send(viewAction: .displayCall)
   182→            }
   183→            .accessibilityIdentifier(A11yIdentifiers.roomScreen.joinCall)
   184→        } else {
   185→            Button {
   186→                context.send(viewAction: .displayCall)
   187→            } label: {
   188→                CompoundIcon(\.videoCallSolid)
   189→            }
   190→            .accessibilityLabel(L10n.a11yStartCall)
   191→            .accessibilityIdentifier(A11yIdentifiers.roomScreen.joinCall)
   192→        }
   193→    }
   194→}
